#include <algorithm>
#include <iterator>
#include <set>
#include <string>
#include <unordered_map>
#include <unordered_set>
#include <vector>

int firstUnique(const std::string& s)
{
    int counts[256] = {};
    for (unsigned char c : s) ++counts[c];
    for (std::size_t i = 0; i < s.size(); ++i)
        if (counts[static_cast<unsigned char>(s[i])] == 1) return static_cast<int>(i);
    return -1;
}

std::vector<std::string> topWords(const std::vector<std::string>& words, std::size_t k)
{
    std::unordered_map<std::string, int> counts;
    for (const auto& w : words) ++counts[w];
    std::vector<std::pair<std::string, int>> all(counts.begin(), counts.end());
    std::sort(all.begin(), all.end(), [](const auto& a, const auto& b) {
        return a.second != b.second ? a.second > b.second : a.first < b.first;
    });
    std::vector<std::string> out;
    for (std::size_t i = 0; i < all.size() && i < k; ++i) out.push_back(all[i].first);
    return out;
}

int longestRun(const std::vector<int>& values)
{
    std::unordered_set<long long> present(values.begin(), values.end());   // long long: x - 1 and x + n cannot overflow
    int best = 0;
    for (long long x : present)
    {
        if (present.count(x - 1)) continue;                // not the start of a run
        int length = 1;
        while (present.count(x + length)) ++length;
        best = std::max(best, length);
    }
    return best;
}

bool nearbyDuplicate(const std::vector<int>& values, std::size_t k)
{
    std::unordered_set<int> window;
    for (std::size_t i = 0; i < values.size(); ++i)
    {
        if (window.count(values[i])) return true;
        window.insert(values[i]);
        if (i >= k) window.erase(values[i - k]);
    }
    return false;
}

std::vector<int> slidingMedians(const std::vector<int>& values, std::size_t k)
{
    std::vector<int> out;
    if (k == 0 || k > values.size()) return out;
    std::multiset<int> window(values.begin(), values.begin() + k);
    auto mid = std::next(window.begin(), k / 2);
    for (std::size_t i = k;; ++i)
    {
        out.push_back(*mid);
        if (i == values.size()) break;
        window.insert(values[i]);                          // equal values go after the existing ones
        if (values[i] < *mid) --mid;                       // the new value landed before the middle
        if (values[i - k] <= *mid) ++mid;                  // the leaving value is at or before the middle
        window.erase(window.lower_bound(values[i - k]));   // mid never points at the erased element
    }
    return out;
}

