#include <limits>

TEST("first unique character") {
    CHECK_EQ(firstUnique("swiss"), 1);
    CHECK_EQ(firstUnique("aabbcc"), -1);
    CHECK_EQ(firstUnique(""), -1);
    CHECK_EQ(firstUnique("z"), 0);
    std::string big(100000, 'a');
    big += "b";
    big += std::string(100000, 'c');
    CHECK_EQ(firstUnique(big), 100000);
}
TEST("top words") {
    std::vector<std::string> w{ "the", "cat", "the", "dog", "a", "cat", "the", "a" };
    CHECK_EQ(topWords(w, 2), (std::vector<std::string>{ "the", "a" }));
    CHECK_EQ(topWords(w, 10), (std::vector<std::string>{ "the", "a", "cat", "dog" }));
    CHECK(topWords({}, 3).empty());
    std::vector<std::string> big;
    for (int i = 0; i < 100000; ++i) big.push_back("w" + std::to_string(i % 1000));   // each 100 times
    for (int i = 0; i < 101; ++i) big.push_back("zz");
    CHECK_EQ(topWords(big, 4), (std::vector<std::string>{ "zz", "w0", "w1", "w10" }));
}
TEST("longest consecutive run") {
    CHECK_EQ(longestRun({ 100, 4, 200, 1, 3, 2 }), 4);
    CHECK_EQ(longestRun({ 0, 3, 7, 2, 5, 8, 4, 6, 0, 1 }), 9);
    CHECK_EQ(longestRun({}), 0);
    CHECK_EQ(longestRun({ 5, 5, 5 }), 1);
    CHECK_EQ(longestRun({ std::numeric_limits<int>::max(), std::numeric_limits<int>::max() - 1 }), 2);
    std::vector<int> big;
    for (int i = 0; i < 100000; ++i) big.push_back((i * 37) % 100000 * 2);   // even numbers only
    CHECK_EQ(longestRun(big), 1);
    for (int i = 0; i < 50000; ++i) big.push_back(i * 2 + 1);                 // fill in the odd ones below 100000
    CHECK_EQ(longestRun(big), 100001);
}
TEST("nearby duplicates") {
    CHECK(nearbyDuplicate({ 1, 2, 3, 1 }, 3));
    CHECK(!nearbyDuplicate({ 1, 2, 3, 1 }, 2));
    CHECK(nearbyDuplicate({ 1, 0, 1, 1 }, 1));
    CHECK(!nearbyDuplicate({}, 5));
    std::vector<int> big(100000);
    for (int i = 0; i < 100000; ++i) big[i] = i % 5000;
    CHECK(!nearbyDuplicate(big, 4999));
    CHECK(nearbyDuplicate(big, 5000));
}
TEST("sliding medians") {
    CHECK_EQ(slidingMedians({ 5, 1, 4, 2, 3 }, 3), (std::vector<int>{ 4, 2, 3 }));
    CHECK_EQ(slidingMedians({ 1, 3, -1, -3, 5, 3, 6, 7 }, 3), (std::vector<int>{ 1, -1, -1, 3, 5, 6 }));
    CHECK_EQ(slidingMedians({ 2, 2, 2, 1, 1 }, 3), (std::vector<int>{ 2, 2, 1 }));
    CHECK_EQ(slidingMedians({ 7 }, 1), (std::vector<int>{ 7 }));
    CHECK(slidingMedians({ 1, 2 }, 3).empty());
    std::vector<int> big(100000);
    for (int i = 0; i < 100000; ++i) big[i] = (i * 7919) % 1000;
    auto m = slidingMedians(big, 101);
    CHECK_EQ(m.size(), std::size_t{ 99900 });
    std::vector<int> w(big.begin() + 5000, big.begin() + 5101);
    std::sort(w.begin(), w.end());
    CHECK_EQ(m[5000], w[50]);
}

